local FALLBACK_SCOPES = {
    "active_skill_gem_stat_descriptions",
    "gem_stat_descriptions",
    "skill_stat_descriptions",
    "meta_gem_stat_descriptions",
    "passive_skill_stat_descriptions",
    "passive_skill_aura_stat_descriptions",
    "utility_flask_buff_stat_descriptions",
    "passive_skill_variant_stat_descriptions",
    "stat_descriptions",
}

---@param scopeName string|nil
---@param statsList string[]|nil
---@return table|nil
function StatDescriptionsRU:Get(scopeName, statsList)
    if not statsList or #statsList == 0 then return nil end
    local key = table.concat(statsList, "|")
    if scopeName then
        local norm = scopeName:gsub("^Specific_Skill_Stat_Descriptions/", "specific_skill_stat_descriptions/")
        local sMap = self.scopes[norm] or self.scopes[scopeName] or self.scopes["specific_skill_stat_descriptions/" .. norm]
        if sMap and sMap[key] then
            return sMap[key]
        end
    end
    for _, fb in ipairs(FALLBACK_SCOPES) do
        local sMap = self.scopes[fb]
        if sMap and sMap[key] then
            return sMap[key]
        end
    end
    return nil
end

return StatDescriptionsRU
